import{_ as a,C as n,o as r,c as s,j as t,a as i,E as c,ak as h}from"./chunks/framework.sV-XtlWr.js";const b=JSON.parse('{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","frontmatter":{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:title","content":"Browser extension | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance."}]]},"headers":[],"relativePath":"features/extension.md","filePath":"features/extension.md","lastUpdated":1790850745000}'),l={name:"features/extension.md"};function d(p,e,g,u,f,m){const o=n("Needs");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"browser-extension",tabindex:"-1"},[i("Browser extension "),t("a",{class:"header-anchor",href:"#browser-extension","aria-label":'Permalink to "Browser extension"'},"​")],-1)),c(o,{extension:""}),e[1]||(e[1]=h('<p>Piwi Picker is a Chrome and Edge extension (Manifest V3) that picks ranked, stable Playwright locators from the page you are looking at, scored by the same engine the dashboard uses, and records a multi-page flow into a runnable TypeScript spec. It works standalone and sends nothing by default; connecting it to a Piwi instance adds what needs your project&#39;s history.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Every tool below runs on the live page, from the toolbar popup. The last three need a <a href="#connecting-to-a-piwi-instance">connection to a Piwi instance</a>; the others never reach it.</p><table tabindex="0"><thead><tr><th>Tool</th><th>For</th></tr></thead><tbody><tr><td><a href="#pick-an-element">Pick an element</a></td><td>a ranked locator for one element, re-checked against the page</td></tr><tr><td><a href="#multi-pick">Multi-pick</a></td><td>the shared pattern of a list&#39;s rows or cards</td></tr><tr><td><a href="#lint-overlay">Lint overlay</a></td><td>the elements that would make bad locator targets</td></tr><tr><td><a href="#assertion-suggester">Assertion suggester</a></td><td><code>expect(...)</code> lines for an element</td></tr><tr><td><a href="#copy-context-for-agent">Copy context for agent</a></td><td>one block about an element for a coding agent</td></tr><tr><td><a href="#record-actions">Record actions</a></td><td>a runnable spec from clicks and fills across pages</td></tr><tr><td><a href="./report-a-bug.html">Report a bug</a></td><td>a failing test and a report of a bug you reproduce</td></tr><tr><td><a href="./devtools.html">Developer tools</a></td><td>in DevTools: the selected element&#39;s locators, the locator console, the session, mocks, viewports</td></tr><tr><td><a href="#matching-functions">Matching functions</a></td><td>a recording that calls your own functions</td></tr><tr><td><a href="#test-functions-against-this-page">Test functions</a></td><td>which of your functions work on this page</td></tr><tr><td><a href="#tested-elements">Tested elements</a></td><td>which elements of this page your tests reach</td></tr></tbody></table><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>Install <strong><a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Piwi Picker from the Chrome Web Store ↗</a></strong>. The listing covers Edge too: click <strong>Allow</strong> on its <em>Allow extensions from other stores</em> banner once, then <strong>Get</strong>.</p><p>Every tool in the popup has a key shown on its tile (<code>1</code> records, <code>2</code> picks, <code>T</code> opens Tested elements, <code>B</code> reports a bug). One tool runs at a time and <strong>Esc</strong> cancels it; recording runs until its own <strong>Stop</strong>. The developer tools that need no pick on the page are in the browser&#39;s DevTools: see <a href="./devtools.html">Developer tools</a>.</p><p>Picking also has a shortcut, suggested as <code>Ctrl+Shift+E</code> (<code>Cmd+Shift+E</code> on macOS); the popup footer shows the key actually bound.</p><h2 id="pick-an-element" tabindex="-1">Pick an element <a class="header-anchor" href="#pick-an-element" aria-label="Permalink to &quot;Pick an element&quot;">​</a></h2><p>Hover highlights, a click picks. The pick snaps to the nearest actionable ancestor (the text inside a button picks the button), and ↑/↓ walk the DOM tree first, showing the locator each step would produce. For an element with a role, an <strong>anchors</strong> step lets you pick stable parents to scope the locator to, with a live match count.</p><p>Every candidate uses the names Playwright computes (a tab with a count badge is <code>{ name: &#39;Regressions 5&#39; }</code>), is scored the way the dashboard scores captured locators, and is run against the page as Playwright runs it. Those that find only the picked element come first. One that also finds others is offered narrowed: exact (<code>{ name: &#39;Failed&#39; }</code> also finds &quot;3 failed&quot;), filtered by its text, or scoped to its landmark, dialog or row, and below it with its count; failing that, <code>.first()</code> or <code>.nth()</code>, with a warning.</p><p>Copy the result as the bare locator, an action line (<code>await page.getByRole(…).click();</code>) or a visibility assertion. <strong>Copy all</strong> copies every ranked locator, one per line, for a project&#39;s <a href="./locator-usage.html#the-locators-page">Locators page</a>.</p><h2 id="multi-pick" tabindex="-1">Multi-pick <a class="header-anchor" href="#multi-pick" aria-label="Permalink to &quot;Multi-pick&quot;">​</a></h2><p>Pick two or three similar items (table rows, cards) to derive the pattern they share, such as <code>getByRole(&#39;row&#39;).filter({ hasText: … })</code>. It warns when only <code>.nth()</code> could tell them apart.</p><h2 id="lint-overlay" tabindex="-1">Lint overlay <a class="header-anchor" href="#lint-overlay" aria-label="Permalink to &quot;Lint overlay&quot;">​</a></h2><p>One click outlines every interactive element no stable locator finds alone, with a suggested <code>data-testid</code> for each and a Markdown checklist.</p><h2 id="assertion-suggester" tabindex="-1">Assertion suggester <a class="header-anchor" href="#assertion-suggester" aria-label="Permalink to &quot;Assertion suggester&quot;">​</a></h2><p>Pick an element to get the <code>expect(...)</code> candidates that apply to it (<code>toHaveValue</code>, <code>toHaveText</code>, <code>toHaveAccessibleName</code>, <code>toBeVisible</code>), built on its top-ranked locator, each with a copy button.</p><h2 id="copy-context-for-agent" tabindex="-1">Copy context for agent <a class="header-anchor" href="#copy-context-for-agent" aria-label="Permalink to &quot;Copy context for agent&quot;">​</a></h2><p>Pick an element to copy one block for a coding agent: the page URL, a summary of the element and every ranked locator.</p><h2 id="record-actions" tabindex="-1">Record actions <a class="header-anchor" href="#record-actions" aria-label="Permalink to &quot;Record actions&quot;">​</a></h2><p><strong>Record actions</strong> asks for access to the site you are on, then captures clicks, double clicks, fills, checks, choices, drags, the names of chosen files (never their content) and the keys that submit, close or move through a list, across pages. A click on what a hover shows (row actions, a hover menu) is recorded after that hover. <strong>Stop</strong> opens the review: <strong>Copy as TypeScript</strong> for a runnable spec that waits for each page it opens, <strong>Download steps</strong> for a <a href="/reference/steps-format.html">steps file</a> to share or render with <a href="/reference/cli.html#codegen"><code>piwi codegen</code></a>, <a href="./editors.html#send-from-piwi-picker"><strong>Send to editor</strong></a>, or <strong>Discard</strong>. Passwords are never captured: the spec reads them from <code>process.env</code>.</p><h2 id="matching-functions" tabindex="-1">Matching functions <a class="header-anchor" href="#matching-functions" aria-label="Permalink to &quot;Matching functions&quot;">​</a></h2><p>With a connection, the recorder loads the <a href="./test-functions.html">function catalog</a> of the project mapped to the page and ranks, while you record, the functions the steps look like. On export, a complete match becomes a call to your function; other steps stay locator lines. No AI: it scores your registered functions&#39; DOM patterns.</p><h2 id="test-functions-against-this-page" tabindex="-1">Test functions against this page <a class="header-anchor" href="#test-functions-against-this-page" aria-label="Permalink to &quot;Test functions against this page&quot;">​</a></h2><p><strong>Test functions</strong> in the popup scores every function of the active project&#39;s catalog against the page as it is now: <strong>Ready to use here</strong> (every step finds one element), <strong>Partly found here</strong>, or <strong>Not on this page</strong>. Its link opens the catalog in Piwi.</p><h2 id="tested-elements" tabindex="-1">Tested elements <a class="header-anchor" href="#tested-elements" aria-label="Permalink to &quot;Tested elements&quot;">​</a></h2><p>With a connection, <a href="./tested-elements.html">Tested elements</a> outlines every element of the page a test of the active project reaches, lists those tests, and marks the buttons, links and fields no test reaches.</p><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>Piwi Picker speaks English, French, German, Spanish and Brazilian Portuguese, following the browser unless <strong>Language</strong>, in the settings, picks another. German, Spanish and Portuguese are unreviewed drafts: <a href="https://github.com/PiwiTests/platform/issues/new?template=translation.yml" target="_blank" rel="noreferrer">suggest a correction</a>. A bug report is written in the extension&#39;s language; page texts, locators, test ids, <code>steps.json</code> and generated specs never are.</p><h2 id="permissions-explained" tabindex="-1">Permissions, explained <a class="header-anchor" href="#permissions-explained" aria-label="Permalink to &quot;Permissions, explained&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>activeTab</code></td><td>acts on the tab you are looking at, only when you click the toolbar icon or press the shortcut</td></tr><tr><td><code>debugger</code> (Chrome and Edge)</td><td>trusted input for a <a href="./replay-a-bug-report.html">replay</a>, a bug report&#39;s console, requests and screenshots, and DevTools&#39; <a href="./devtools.html#slow-down-or-fail-a-request">throttling</a>. Attached only while one of them runs, under Chrome&#39;s bar saying Piwi Picker started debugging the browser; <strong>Cancel</strong> there falls back to the page&#39;s own events. Nothing leaves your machine</td></tr><tr><td><code>scripting</code></td><td>injects the picker or the recorder into that tab on demand; no content script runs on pages you did not ask it to</td></tr><tr><td><code>storage</code></td><td>keeps your copy format and, only if you connect, the instance URL, API key, URL patterns, cached catalogs and the last three <a href="./tested-elements.html">locator indexes</a>, on your machine. The session and the running recording use <code>chrome.storage.session</code>, cleared when the browser closes</td></tr><tr><td><code>cookies</code> (optional, not granted in advance)</td><td><a href="./devtools.html#save-login-for-tests">Save login for tests</a> asks for it, for the one site whose login you save</td></tr><tr><td><code>optional_host_permissions</code> (none granted in advance)</td><td>recording asks for the one site you are on, to follow you across its pages; a connection asks for your instance&#39;s origin. Never <code>&lt;all_urls&gt;</code></td></tr></tbody></table><h2 id="connecting-to-a-piwi-instance" tabindex="-1">Connecting to a Piwi instance <a class="header-anchor" href="#connecting-to-a-piwi-instance" aria-label="Permalink to &quot;Connecting to a Piwi instance&quot;">​</a></h2><p>Optional and off by default. In the settings (the popup&#39;s gear button), type your instance&#39;s address and click <strong>Connect</strong>, then <strong>Allow</strong> in the tab that opens: Piwi Picker receives its own API key. Which project applies on a page comes from URL patterns kept on the instance, per project, and from any you keep in this browser; the popup&#39;s <strong>Active project</strong> select overrides both for the session. See <a href="./extension-connection.html">Extension connection</a>.</p><p>Function catalogs refresh in the background; <strong>Refresh</strong> in Test functions fetches them now. <strong>A recording is never sent to your instance</strong>, and a <a href="./bug-reports.html">bug report</a> only from its preview.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One frame at a time.</strong> The picker and the recorder see the top-level document, not iframes or shadow DOM.</li><li><strong>Recording covers one origin.</strong> On another site, recording stops capturing steps; stop and review, or start again there.</li><li><strong>No aria-snapshot copier</strong> yet for <code>toMatchAriaSnapshot()</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: from a failing locator to the one to use instead</li><li><a href="./extension-connection.html">Extension connection</a>: connecting in one step, and the URL patterns kept on the instance</li><li><a href="./tested-elements.html">Tested elements</a>: the elements your tests reach, drawn on the page</li><li><a href="./test-functions.html">Test functions catalog</a>: the functions a recording can call</li><li><a href="./locator-healing.html">Locator healing</a>: the replacement Piwi proposes after a failure</li></ul>',39))])}const k=a(l,[["render",d]]);export{b as __pageData,k as default};
